/** Note width buckets (world units): half-lane steps from 0.5 to 12.0 lanes. */
export const hitFxBucket = (w: number) => Math.min(23, Math.max(0, Math.floor(w / 0.796667 - 0.5)))

/** Simple effect block for a native judgement (every note kind shares it). */
export const hitFxFirst = (_kind: number, judgment: number) => {
    if (judgment >= 5) return 0.0
    if (judgment === 4) return 192.0
    if (judgment === 3) return 384.0
    if (judgment === 2) return 528.0
    return -1
}

/** Simple effect block for a native judgement (every note kind shares it). */
export const hitFxCount = (_kind: number, judgment: number) => {
    if (judgment >= 5) return 8.0
    if (judgment === 4) return 8.0
    if (judgment === 3) return 6.0
    if (judgment === 2) return 3.0
    return 0
}

/** Simple effect block for a native judgement (every note kind shares it). */
export const hitFxDuration = (_kind: number, judgment: number) => {
    if (judgment >= 5) return 0.416667
    if (judgment === 4) return 0.416667
    if (judgment === 3) return 0.416667
    if (judgment === 2) return 0.416667
    return 0
}

export const LOOP_FX_FIRST = 600
export const LOOP_FX_COUNT = 5
export const LOOP_FX_DURATION = 0.416667
